function isBalanced(root) {
  const h = (n) => {
    if (!n) return 0
    const l = h(n.left)
    if (l === -1) return -1
    const r = h(n.right)
    if (r === -1) return -1
    if (Math.abs(l - r) > 1) return -1
    return 1 + Math.max(l, r)
  }
  return h(root) !== -1
}
